// ── Number to Indian words ────────────────────────────────────────────────────
function numToWordsIN(amount) {
  const ones = ['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  const tens = ['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  function conv(n) {
    if (n < 20) return ones[n];
    if (n < 100) return tens[Math.floor(n/10)] + (n%10 ? ' '+ones[n%10] : '');
    if (n < 1000) return ones[Math.floor(n/100)] + ' Hundred' + (n%100 ? ' '+conv(n%100) : '');
    return '';
  }
  let n = Math.floor(Math.abs(amount)), r = '';
  if (n >= 10000000) { r += conv(Math.floor(n/10000000))+' Crore '; n %= 10000000; }
  if (n >= 100000)   { r += conv(Math.floor(n/100000))+' Lakh '; n %= 100000; }
  if (n >= 1000)     { r += conv(Math.floor(n/1000))+' Thousand '; n %= 1000; }
  if (n > 0)         { r += conv(n); }
  return r.trim() ? 'Rupees ' + r.trim() + ' Only' : 'Zero Only';
}

// ── Normalize inclusions ──────────────────────────────────────────────────────
function fmtInclusions(val) {
  if (!val) return '';
  if (Array.isArray(val)) {
    return val.map(function(item) {
      if (typeof item === 'string') return item;
      return item.metric ? item.text + ' ' + item.metric : item.text;
    }).filter(Boolean).join('<br/>');
  }
  return val;
}

// ── Step-up cycles helper (mirrors formatting.js for popup window context) ────
var cyclesInDateRange = function(startDate, endDate, billingCycle) {
  if (!startDate || !endDate) return 0;
  var s = new Date(startDate);
  var e = new Date(endDate);
  var eExcl = new Date(e.getTime() + 86400000);
  var totalMonths = (eExcl.getFullYear() - s.getFullYear()) * 12 + (eExcl.getMonth() - s.getMonth());
  if (totalMonths <= 0) return 0;
  var m = { Monthly:1, Quarterly:3, 'Bi-Annually':6, Annually:12 }[billingCycle];
  if (!m) return 1;
  return Math.max(1, Math.floor(totalMonths / m));
};

